CREATE OR REPLACE FUNCTION public.enforce_order_item_ingredient_restrictions() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog', 'public', 'auth' AS $function$ DECLARE v_student_user_id uuid; v_ingredients text; v_ingredients_verified boolean; BEGIN SELECT o.user_id INTO v_student_user_id FROM public.orders o WHERE o.id = NEW.order_id; IF v_student_user_id IS NULL THEN RETURN NEW; END IF; IF NOT EXISTS (SELECT 1 FROM public.student_ingredient_blocks b WHERE b.student_user_id = v_student_user_id) THEN RETURN NEW; END IF; SELECT n.ingredients, n.ingredients_verified INTO v_ingredients, v_ingredients_verified FROM public.product_nutrition n WHERE n.product_id = NEW.product_id; IF NOT FOUND OR COALESCE(v_ingredients_verified, false) IS DISTINCT FROM true OR length(trim(COALESCE(v_ingredients, ''))) = 0 THEN RAISE EXCEPTION 'food_ingredients_unverified' USING DETAIL = 'El alimento no tiene una lista de ingredientes verificada por la cafetería.'; END IF; IF EXISTS (SELECT 1 FROM public.student_ingredient_blocks b CROSS JOIN LATERAL regexp_split_to_table(v_ingredients, E'[,;\n\r]+') AS ingredient(value) WHERE b.student_user_id = v_student_user_id AND position(' ' || b.ingredient_key || ' ' IN ' ' || trim(regexp_replace(lower(ingredient.value), '[^[:alnum:]]+', ' ', 'g')) || ' ') > 0) THEN RAISE EXCEPTION 'blocked_ingredient_in_product' USING DETAIL = 'El alimento contiene un ingrediente bloqueado en las preferencias del estudiante.'; END IF; RETURN NEW; END; $function$; REVOKE ALL ON FUNCTION public.enforce_order_item_ingredient_restrictions() FROM PUBLIC, anon, authenticated; GRANT EXECUTE ON FUNCTION public.enforce_order_item_ingredient_restrictions() TO service_role; DROP TRIGGER IF EXISTS order_items_enforce_ingredient_restrictions ON public.order_items; CREATE TRIGGER order_items_enforce_ingredient_restrictions BEFORE INSERT ON public.order_items FOR EACH ROW EXECUTE FUNCTION public.enforce_order_item_ingredient_restrictions();